import random

def round_cave(knows_password, rng):
    """Un round del protocollo della caverna. True se Alice esce dal ramo richiesto."""
    entered = rng.choice("AB")        # Alice entra da un ramo a caso (Bob non guarda)
    challenge = rng.choice("AB")      # Bob grida un ramo a caso
    if entered == challenge:
        return True                   # esce da dove è entrata
    return knows_password             # deve attraversare la porta: serve la password

def run_protocol(knows_password, n, rng):
    return all(round_cave(knows_password, rng) for _ in range(n))

rng = random.Random(42)
TRIALS = 200_000
print("n  honest  cheater_sim  2^-n")
for n in (1, 2, 5, 10):
    honest = sum(run_protocol(True, n, rng) for _ in range(TRIALS)) / TRIALS
    cheat = sum(run_protocol(False, n, rng) for _ in range(TRIALS)) / TRIALS
    print(f"{n:<2} {honest:.3f}   {cheat:.5f}      {2**-n:.5f}")

